insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_93_v1'
from (values
('127.746.d.1.A',3,'A cadet writes a clear incident summary using correct spelling, grammar and complete sentences. This applies:','["English language arts skills needed in public safety careers", "only math skills", "only artistic skills", "no particular skills"]'::jsonb,0,'Reports depend on strong writing.','original'),
('127.746.d.1.A',4,'Why do academy instructors grade cadets'' written reports for grammar and organization?','["Reports are never read", "Reports may be used as legal records and must be clear", "Grammar is only a hobby", "Spelling does not matter in court"]'::jsonb,1,'Written reports can become evidence.','original'),
('127.746.d.1.B',3,'A dispatcher calculates how many minutes a unit needs to travel 12 miles at 36 miles per hour. This applies:','["music skills", "no skills", "mathematics skills used in public safety careers", "art skills"]'::jsonb,2,'12 ÷ 36 hour = 20 minutes.','original'),
('127.746.d.1.B',4,'A patrol unit covers 45 miles in 1.5 hours. Its average speed is:','["45 miles per hour", "67.5 miles per hour", "15 miles per hour", "30 miles per hour"]'::jsonb,3,'45 ÷ 1.5 = 30.','original'),
('127.746.d.1.C',3,'A crime-scene technician learns why fingerprints are unique to each person. This applies:','["science knowledge used in law and public safety careers", "no science", "only cooking skills", "only drawing skills"]'::jsonb,0,'Forensics relies on biology and chemistry.','original'),
('127.746.d.1.C',4,'Which science concept helps a fire investigator explain why a fire spread quickly in a room full of dry paper?','["Gravity stops fires", "Fuel type and heat transfer affect how fast a fire grows", "Fires ignore materials", "Paper cannot burn"]'::jsonb,1,'Combustion science explains fire behavior.','original'),
('127.746.d.2.A',3,'A new officer says ''me and him was there'' in a briefing. A better evaluation of grammar would be to say:','["''He and me was there''", "''Me and him were there''", "''He and I were there''", "''Him and me was there''"]'::jsonb,2,'Standard grammar helps professional communication.','original'),
('127.746.d.2.A',4,'Why does correct grammar matter in verbal communication for public safety workers?','["It makes talk slower only", "It is only for writers", "It has no effect on listeners", "It makes instructions clear and keeps the speaker credible"]'::jsonb,3,'Clear speech prevents misunderstandings.','original'),
('127.746.d.2.B',3,'A firefighter gives short, firm commands to a crowd near a blaze but speaks gently to a frightened child. This shows:','["choosing different speaking strategies for different audiences", "using one tone only", "ignoring listeners", "avoiding communication"]'::jsonb,0,'Speaking style should fit the situation.','original'),
('127.746.d.2.B',4,'Which strategy best fits informing a large crowd about an evacuation?','["Speak only to one person", "Speak loudly, clearly and give short step-by-step directions", "Whisper long explanations", "Use slang and jokes"]'::jsonb,1,'Crowds need short clear commands.','original'),
('127.746.d.2.C',3,'A caller''s trembling voice and fast speech tell a 911 operator the caller is frightened. This is an example of interpreting:','["written grammar", "badge number", "voice quality and delivery", "uniform color"]'::jsonb,2,'Tone and pace carry information.','original'),
('127.746.d.2.C',4,'A calm, steady, low voice used with an upset person is most likely to:','["increase panic", "end the conversation", "hide the message", "help de-escalate the situation"]'::jsonb,3,'Calm delivery reduces tension.','original'),
('127.746.d.2.D',3,'A police dispatcher and an EMT cooperate politely during a shared call. This demonstrates:','["interpersonal skills needed to work with coworkers", "workplace conflict", "avoidance", "poor teamwork"]'::jsonb,0,'Respect and cooperation help teams.','original'),
('127.746.d.2.D',4,'A coworker misunderstands your instructions during a shift. The best interpersonal response is to:','["shout", "restate the instructions calmly and check understanding", "blame them publicly", "ignore them"]'::jsonb,1,'Clarity and respect resolve confusion.','original'),
('127.746.d.3.A',3,'A security supervisor studies repeated after-hours alarms and proposes adding cameras. This is:','["avoiding the problem", "ignoring data", "using analytical skills to form a proposal", "guessing"]'::jsonb,2,'Analysis supports proposals.','original'),
('127.746.d.3.A',4,'Which step best supports a proposal to change patrol routes?','["Copying another city exactly", "Ignoring reports", "Choosing routes by coin toss", "Reviewing incident data to find where problems occur most"]'::jsonb,3,'Data should drive solutions.','original'),
('127.746.d.3.B',3,'A sheriff''s office designs a plan so that rural residents can reach a deputy faster. This is:','["formulating a solution that ensures delivery of services", "ending service", "hiding service", "reducing service"]'::jsonb,0,'Service plans aim to reach people.','original'),
('127.746.d.3.B',4,'A proposal to improve 911 response times should explain:','["only past mistakes", "what will change and how it will help residents", "only the logo", "nothing"]'::jsonb,1,'Good proposals show benefit.','original'),
('127.746.d.3.C',3,'A correctional officer is asked to look away from a rule violation by a friend. Using critical thinking, the officer should:','["let the friend decide", "ignore the policy", "weigh the ethics and follow the rules and policy", "hide the violation"]'::jsonb,2,'Ethical issues require principled decisions.','original'),
('127.746.d.3.C',4,'A guard sees a coworker accept a gift from an inmate''s family. Critical thinking about the ethical problem leads to:','["deleting records", "joining in", "ignoring it", "reporting the violation through proper channels"]'::jsonb,3,'Policy requires reporting.','original'),
('127.746.d.4.A',3,'Comparing the risks faced by a firefighter, a patrol officer and a corrections officer is an example of:','["identifying and analyzing dangers in different career fields", "ignoring risks", "choosing jobs randomly", "avoiding safety"]'::jsonb,0,'Each field has distinct hazards.','original'),
('127.746.d.4.A',4,'Which danger is most closely tied to firefighting?','["Paper cuts only", "Exposure to smoke, heat and structural collapse", "Lack of air conditioning only", "Eye strain only"]'::jsonb,1,'Fire scenes include heat, smoke and collapse.','original'),
('127.746.d.4.B',3,'After several back injuries, a department recommends lifting training and better equipment. This is:','["ignoring injuries", "punishing victims", "creating strategies for employee safety and health", "removing safety rules"]'::jsonb,2,'Strategies prevent repeat injuries.','original'),
('127.746.d.4.B',4,'A good strategy to reduce injuries at an emergency scene is to:','["skip training", "remove helmets", "work faster without checks", "provide training and require protective equipment"]'::jsonb,3,'Training and PPE protect workers.','original'),
('127.746.d.4.C',3,'Chemicals in a damaged truck leak near a roadway. Responders should:','["follow hazardous materials handling procedures", "drive through it", "touch the liquid", "ignore the spill"]'::jsonb,0,'Hazmat requires special handling.','original'),
('127.746.d.4.C',4,'Safety Data Sheets help responders by listing a chemical''s:','["delivery date", "hazards and safe handling and first aid information", "price", "color of the label"]'::jsonb,1,'SDS describe hazards and precautions.','original'),
('127.746.d.4.D',3,'A fire academy requires regular workouts because good health and fitness help firefighters:','["avoid all training", "skip rest", "perform physically demanding duties safely", "avoid teamwork"]'::jsonb,2,'Fitness supports job performance.','original'),
('127.746.d.4.D',4,'Which habit best supports long-term fitness for a public safety worker?','["Eating only snacks", "Avoiding all exercise", "Skipping sleep", "Regular exercise, sleep and balanced eating"]'::jsonb,3,'Healthy habits sustain readiness.','original'),
('127.746.d.4.E',3,'A responder finds an adult who is not breathing and has no pulse. The responder should begin CPR and:','["use an automated external defibrillator if one is available", "leave the scene", "wait without acting", "give water"]'::jsonb,0,'CPR plus AED can restart a heart.','original'),
('127.746.d.4.E',4,'The purpose of an AED on a person in cardiac arrest is to:','["take blood pressure", "analyze the heart rhythm and deliver a shock if needed", "lower temperature", "measure height"]'::jsonb,1,'AEDs can restore a normal rhythm.','original'),
('127.746.d.5.A',3,'A trainee discusses whether an officer should keep a found wallet. This examination of an ethical dilemma focuses on:','["clothing only", "weather only", "professional conduct and honesty", "speed only"]'::jsonb,2,'Ethics guide conduct.','original'),
('127.746.d.5.A',4,'Which choice shows professional conduct for a guard who notices a coworker sleeping on duty?','["Hide it forever", "Join in", "Post it online", "Follow policy and report the problem appropriately"]'::jsonb,3,'Professionals follow policy.','original'),
('127.746.d.5.B',3,'An officer must obey search-and-seizure rules set by the Fourth Amendment and department policy. These are examples of:','["laws, regulations and policies governing professionals", "suggestions only", "jokes", "myths"]'::jsonb,0,'Professionals are bound by law and policy.','original'),
('127.746.d.5.B',4,'A department policy tells officers how and when force may be used. This type of rule is:','["optional advice", "a policy that governs professional behavior", "a random opinion", "a game rule"]'::jsonb,1,'Policies guide lawful conduct.','original'),
('127.746.d.5.C',3,'A supervisor asks a security guard to falsify a log. The best strategy is to:','["comply quietly", "ignore the problem", "refuse and report the request through proper channels", "delete the log"]'::jsonb,2,'Unethical orders must be reported.','original'),
('127.746.d.5.C',4,'An officer learns a coworker is stealing evidence. Which response recommends the right strategy?','["Take a share", "Warn the coworker", "Hide the evidence", "Report it to a supervisor or internal affairs"]'::jsonb,3,'Illegal acts must be reported.','original'),
('127.746.d.6.A',3,'After a major accident, police, fire, EMS and the court system each play a role. Discussing their importance shows how:','["public safety agencies depend on one another", "only police matter", "agencies never meet", "each works alone"]'::jsonb,0,'Agencies work together.','original'),
('127.746.d.6.A',4,'Which statement best explains why the court and corrections systems matter to public safety?','["They replace police", "They hold offenders accountable and keep the community safe", "They only handle paperwork", "They end all crime"]'::jsonb,1,'They complete the justice process.','original'),
('127.746.d.6.B',3,'The first person to arrive at a car crash checks for danger, calls for help and gives basic aid. This is a typical:','["tourist role", "spectator role", "first responder role and responsibility", "reporter role"]'::jsonb,2,'First responders provide immediate care.','original'),
('127.746.d.6.B',4,'Which is a first responder''s responsibility at the scene of an emergency?','["Leave for lunch", "Ignore injuries", "Block help", "Make the scene safe and give immediate aid until others arrive"]'::jsonb,3,'Safety and aid come first.','original'),
('127.746.d.6.C',3,'A highway crash happens on the border of two counties, and both sheriff''s offices argue over who should lead. This is a:','["jurisdictional problem", "dress code problem", "staffing holiday", "weather problem"]'::jsonb,0,'Jurisdiction is who has authority.','original'),
('127.746.d.6.C',4,'A good way to reduce jurisdictional confusion at a multi-agency scene is to:','["stop communicating", "use a clear command structure and shared communication", "ignore the boundary", "let each agency act alone"]'::jsonb,1,'Clear command prevents conflict.','original'),
('127.746.d.6.D',3,'A mall security guard can ask a rowdy visitor to leave private property, while a police officer can make an arrest under public authority. This shows that the roles:','["are identical", "have no limits", "differ between private security and public law enforcement", "never overlap with laws"]'::jsonb,2,'Authority differs.','original'),
('127.746.d.6.D',4,'Which task is usually done by a police officer but not by a typical private guard?','["Checking visitor badges", "Walking a patrol route", "Watching a door", "Making arrests under the authority of the government"]'::jsonb,3,'Police hold public arrest powers.','original'),
('127.746.d.7.A',3,'Laws in the United States come from the Constitution, statutes, court decisions and regulations. These are:','["sources of law", "advertising", "sports rules", "rumors"]'::jsonb,0,'Law has several sources.','original'),
('127.746.d.7.A',4,'Which is a source of law created by legislatures?','["traditions of one family", "statutes", "jokes", "myths"]'::jsonb,1,'Legislatures write statutes.','original'),
('127.746.d.7.B',3,'The Fourth Amendment protects people from unreasonable searches. This shows the Constitution''s impact on:','["weather reports", "school lunches", "how criminal law is enforced", "sports scores"]'::jsonb,2,'Constitutional limits shape policing.','original'),
('127.746.d.7.B',4,'The Sixth Amendment gives an accused person the right to:','["avoid all charges", "skip court forever", "choose the judge''s salary", "a speedy public trial and a lawyer"]'::jsonb,3,'Trial rights come from the Bill of Rights.','original'),
('127.746.d.7.C',3,'Theft of a candy bar is usually a misdemeanor, while armed robbery is a felony. The difference is mostly:','["how serious the crime and punishment are", "the color of the weapon", "the weather", "the day of the week"]'::jsonb,0,'Felonies are more serious.','original'),
('127.746.d.7.C',4,'Which punishment is generally linked to a felony conviction?','["a verbal chat only", "imprisonment for more than one year", "a parking sticker", "a library fine"]'::jsonb,1,'Felonies carry heavier penalties.','original'),
('127.746.d.7.D',3,'To convict someone of burglary, the state must prove each essential element, such as unlawful entry and intent. This is:','["ignoring facts", "guessing", "analyzing the elements of a crime", "skipping evidence"]'::jsonb,2,'All elements must be proved.','original'),
('127.746.d.7.D',4,'The elements of a crime generally include the criminal act and:','["a uniform", "a witness''s age only", "a lucky outcome", "a guilty mental state when required"]'::jsonb,3,'Act and intent are common elements.','original'),
('127.746.d.7.E',3,'Officers sometimes struggle to prove a case when witnesses will not testify. This is a:','["problem commonly associated with enforcing criminal laws", "law-free zone", "perfect system", "guaranteed win"]'::jsonb,0,'Evidence and cooperation can be hard to secure.','original'),
('127.746.d.7.E',4,'Which problem often complicates enforcing criminal laws?','["too many holidays", "limited resources and difficulty gathering reliable evidence", "friendly neighbors", "uniform colors"]'::jsonb,1,'Resources and evidence limit enforcement.','original'),
('127.746.d.7.F',3,'A bill passes the House and Senate and is signed by the governor. This shows:','["how a trial works", "how a jail runs", "how a law is enacted", "how a patrol is planned"]'::jsonb,2,'Legislatures pass and executives sign bills.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_93_v1'
from (values
('127.746.d.7.F',4,'Before a bill becomes a state law in Texas, it must be passed by both chambers and then:','["burned", "approved by the weather", "tried in court", "signed by the governor or become law without a veto"]'::jsonb,3,'The governor signs or allows it.','original'),
('127.746.d.8.A',3,'A student can become a city police officer, a county deputy, a state trooper or a federal agent. This lists:','["career opportunities in law enforcement", "school rules", "cooking jobs", "sports teams"]'::jsonb,0,'Careers exist at all levels.','original'),
('127.746.d.8.A',4,'Which agency would employ a Texas state trooper?','["a private mall", "Texas Department of Public Safety", "a city library", "a school cafeteria"]'::jsonb,1,'Troopers work for the DPS.','original'),
('127.746.d.8.B',3,'To become a Texas peace officer, a person must usually finish an academy and pass a licensing exam. This identifies:','["a membership card", "only a haircut", "required education and training for law enforcement", "no training"]'::jsonb,2,'Licensing requires training.','original'),
('127.746.d.8.B',4,'Compared with a local officer, a federal agent usually needs:','["only a uniform", "no education", "only a hobby", "a college degree and specialized agency training"]'::jsonb,3,'Federal roles have higher requirements.','original'),
('127.746.d.8.C',3,'Early American policing began with night watchmen and sheriffs before modern police departments formed. This is part of the:','["history of policing in the United States", "history of music", "history of sports", "history of cooking"]'::jsonb,0,'Policing evolved over time.','original'),
('127.746.d.8.C',4,'The first modern-style municipal police departments in the U.S. appeared mostly during the:','["1700s in ships", "1800s in large cities", "2000s in space", "1500s in forests"]'::jsonb,1,'Large cities created police forces in the 1800s.','original'),
('127.746.d.8.D',3,'Patrolling, answering calls and writing reports are all:','["entertainment", "unrelated tasks", "roles and responsibilities of law enforcement professionals", "hobbies"]'::jsonb,2,'These are core duties.','original'),
('127.746.d.8.D',4,'An officer''s responsibility to enforce laws fairly means the officer must:','["ignore rights", "pick favorites", "skip procedures", "treat people equally and follow the law"]'::jsonb,3,'Fair enforcement is required.','original'),
('127.746.d.8.E',3,'Rules about when an officer may arrest someone or use force come from constitutional law. This is the:','["impact of constitutional law on police actions", "effect of fashion", "effect of weather", "effect of snacks"]'::jsonb,0,'Constitutional limits shape police power.','original'),
('127.746.d.8.E',4,'Which standard must usually be met before an officer can make an arrest?','["a coin flip", "probable cause", "a rumor", "a hunch only"]'::jsonb,1,'Arrests require probable cause.','original'),
('127.746.d.8.F',3,'Paramedics treat injured people on-scene and transport them to a hospital. This shows the role of:','["traffic signs", "jail cooks", "emergency medical services in public safety", "court clerks"]'::jsonb,2,'EMS provides emergency care.','original'),
('127.746.d.8.F',4,'EMS contributes to public safety by:','["grading papers", "writing tickets", "building roads", "giving rapid medical care and transport during emergencies"]'::jsonb,3,'EMS saves lives.','original'),
('127.746.d.8.G',3,'After a difficult call, a dispatcher talks with a peer support team and takes a walk. This is:','["managing the stress of public safety work", "ignoring needs", "hiding feelings forever", "avoiding recovery"]'::jsonb,0,'Healthy coping reduces stress.','original'),
('127.746.d.8.G',4,'Which habit helps public safety professionals manage job-related stress?','["Skipping sleep", "Exercise, rest and talking with trusted peers or counselors", "Isolating", "Refusing help"]'::jsonb,1,'Support and healthy habits help.','original'),
('127.746.d.9.A',3,'A student could work as a court clerk, bailiff or probation officer. This identifies:','["only kitchen jobs", "only police jobs", "career opportunities in the court systems", "only teaching jobs"]'::jsonb,2,'Courts employ many roles.','original'),
('127.746.d.9.A',4,'Which job helps keep order and security in a courtroom?','["painter", "cook", "pilot", "bailiff"]'::jsonb,3,'Bailiffs maintain courtroom order.','original'),
('127.746.d.9.B',3,'A city municipal court handles minor offenses, while a district court handles more serious cases. This identifies:','["levels and functions of criminal courts", "school grades", "recipes", "bus routes"]'::jsonb,0,'Courts differ by level.','original'),
('127.746.d.9.B',4,'A court that reviews whether a trial court made a legal error is a:','["city council", "court of appeals", "jury", "traffic light"]'::jsonb,1,'Appeals courts review legal error.','original'),
('127.746.d.9.C',3,'The judge, prosecutor and defense attorney are part of the:','["audience only", "police squad", "courtroom work group", "jury only"]'::jsonb,2,'They work together in the court process.','original'),
('127.746.d.9.C',4,'Which member of the courtroom work group presents the state''s case against the accused?','["the defendant", "the bailiff", "the juror", "the prosecutor"]'::jsonb,3,'Prosecutors represent the government.','original'),
('127.746.d.9.D',3,'Before trial, the accused appears at an arraignment to hear the charges and enter a plea. This is an example of:','["pretrial procedures", "parole review", "post-trial appeals", "sentencing"]'::jsonb,0,'Arraignment is pretrial.','original'),
('127.746.d.9.D',4,'During a trial, jurors are asked to decide:','["what time court ends", "whether the evidence proves guilt beyond a reasonable doubt", "who pays the judge", "the weather"]'::jsonb,1,'The standard is beyond a reasonable doubt.','original'),
('127.746.d.9.E',3,'A judge orders probation instead of prison for a first-time offender. This is a type of:','["arrest", "booking", "sentencing", "bail"]'::jsonb,2,'Probation is a sentence.','original'),
('127.746.d.9.E',4,'A sentence that allows an offender to remain in the community under supervision is:','["an acquittal", "a pardon", "an arraignment", "probation"]'::jsonb,3,'Probation allows supervised release.','original'),
('127.746.d.10.A',3,'A student could become a probation officer, parole officer or correctional officer. This explains:','["career opportunities in the correctional system", "only banking careers", "only farm careers", "only film careers"]'::jsonb,0,'Corrections includes several careers.','original'),
('127.746.d.10.A',4,'A professional who supervises offenders released from prison before their sentence ends is a:','["court reporter", "parole officer", "bailiff", "dispatcher"]'::jsonb,1,'Parole officers supervise releases.','original'),
('127.746.d.10.B',3,'Supervising inmates, enforcing rules and keeping order are:','["courtroom duties", "hobbies", "duties of a correctional officer", "fire duties"]'::jsonb,2,'These are core duties.','original'),
('127.746.d.10.B',4,'A correctional officer must watch inmates, keep the facility secure and:','["ignore rules", "leave the post", "avoid documentation", "write accurate reports about incidents"]'::jsonb,3,'Reports are required.','original'),
('127.746.d.10.C',3,'Early American prisons, such as those that used solitary reflection, were created to:','["punish offenders and encourage reform", "feed tourists", "entertain crowds", "train astronauts"]'::jsonb,0,'Early prisons aimed at reform.','original'),
('127.746.d.10.C',4,'The idea of a penitentiary was based on the belief that offenders could:','["avoid punishment", "reflect and reform through isolation and labor", "never change", "earn trophies"]'::jsonb,1,'Penitentiaries emphasized reform.','original'),
('127.746.d.10.D',3,'A person arrested Friday is held for a few days in the county facility awaiting a hearing, while a convicted felon serves years elsewhere. The first place is a jail and the second is a:','["library", "court", "prison", "hospital"]'::jsonb,2,'Jails hold short-term; prisons hold long-term.','original'),
('127.746.d.10.D',4,'Which best distinguishes a jail from a prison?','["They are identical", "Jails are for juveniles only", "Jails are only for felons with long sentences", "Jails hold people awaiting trial or serving short sentences"]'::jsonb,3,'Jails are short-term.','original'),
('127.746.d.10.E',3,'A facility labeled minimum, medium or maximum security reflects:','["levels of security in prisons and jails", "school grade levels", "classroom sizes", "ticket prices"]'::jsonb,0,'Facilities are classified by security level.','original'),
('127.746.d.10.E',4,'Which type of facility houses inmates who pose the highest risk?','["a visitor center", "maximum security", "minimum security", "an arraignment hall"]'::jsonb,1,'Maximum security is the strictest.','original'),
('127.746.d.10.F',3,'Inmates still keep certain protections, such as freedom from cruel and unusual punishment. These are:','["no rights", "only rumors", "constitutional rights of inmates", "privileges of staff"]'::jsonb,2,'The Eighth Amendment still applies.','original'),
('127.746.d.10.F',4,'The Eighth Amendment protects inmates from:','["all rules", "all meals", "all supervision", "cruel and unusual punishment"]'::jsonb,3,'Inmates keep this protection.','original'),
('127.746.d.11.A',3,'A person could be a security guard, a loss-prevention agent or a private investigator. This explains:','["career opportunities in private security", "only teaching careers", "only fire careers", "only court careers"]'::jsonb,0,'Private security has many roles.','original'),
('127.746.d.11.A',4,'Which job is typically found in private security?','["state trooper", "retail loss-prevention officer", "county sheriff", "judge"]'::jsonb,1,'Retail stores use loss-prevention staff.','original'),
('127.746.d.11.B',3,'Private security grew in the United States as businesses and railroads hired guards to protect property. This is part of the:','["history of cooking", "history of music", "history and importance of private security", "history of toys"]'::jsonb,2,'Business needs drove its growth.','original'),
('127.746.d.11.B',4,'Private security is important to society because it:','["ends crime", "replaces all police", "has no laws", "protects people and property that public agencies cannot always cover"]'::jsonb,3,'It supplements public safety.','original'),
('127.746.d.11.C',3,'A mall guard calls the police after catching a thief and gives a statement. This shows the:','["relationship between private security and public safety agencies", "rivalry only", "identical authority", "no connection"]'::jsonb,0,'The two cooperate.','original'),
('127.746.d.11.C',4,'Private security most often helps public police by:','["making arrests in every city", "reporting crimes and sharing information", "blocking investigations", "ignoring crimes"]'::jsonb,1,'They share information.','original'),
('127.746.d.12.A',3,'Becoming a firefighter, arson investigator or fire inspector are examples of:','["sports careers", "cooking careers", "career opportunities in fire protection services", "court careers"]'::jsonb,2,'Fire services have many roles.','original'),
('127.746.d.12.A',4,'A professional who examines buildings for fire-code violations is a:','["bailiff", "dispatcher", "parole officer", "fire inspector"]'::jsonb,3,'Inspectors enforce fire codes.','original'),
('127.746.d.12.B',3,'Fighting fires, rescuing people and giving emergency medical aid are:','["duties and responsibilities of firefighters", "bank duties", "school duties", "court duties"]'::jsonb,0,'These are core firefighter duties.','original'),
('127.746.d.12.B',4,'A firefighter''s responsibilities go beyond fires to include:','["only parades", "medical aid and rescue calls", "only driving trucks for fun", "only paperwork"]'::jsonb,1,'Many calls are medical.','original'),
('127.746.d.12.C',3,'A 911 call-taker enters an address in a computer-aided dispatch system so the nearest unit is sent. This shows the importance of:','["ignoring calls", "paper maps only", "911 operations and computer-aided dispatch", "guessing"]'::jsonb,2,'CAD speeds the response.','original'),
('127.746.d.12.C',4,'Computer-aided dispatch helps responders by:','["hiding units", "deleting records", "slowing calls", "tracking calls and units to send the closest help quickly"]'::jsonb,3,'CAD coordinates resources.','original'),
('127.746.d.12.D',3,'A house fire with an injured resident requires police to control traffic, firefighters to fight the fire and EMS to treat the victim. This shows the:','["relationships among police, fire and emergency medical services", "no teamwork", "single agency work", "lack of cooperation"]'::jsonb,0,'Agencies coordinate at scenes.','original'),
('127.746.d.12.D',4,'Why do police, fire and EMS train together?','["to avoid contact", "to coordinate during joint emergency responses", "to switch jobs", "to compete"]'::jsonb,1,'Joint training improves coordination.','original'),
('127.746.d.13.A',3,'A student joins a career and technical student organization such as SkillsUSA and a law enforcement explorer post. This is:','["avoiding involvement", "ignoring careers", "participating in community and career organizations", "quitting school"]'::jsonb,2,'Organizations build skills.','original'),
('127.746.d.13.A',4,'A benefit of joining an organization like SkillsUSA is:','["avoiding teamwork", "ending training", "losing opportunities", "building leadership and career skills"]'::jsonb,3,'They support career readiness.','original'),
('127.746.d.13.B',3,'Neighbors form a Citizens on Patrol group to watch for suspicious activity and report it. This is a:','["community outreach organization", "school club for sports only", "private army", "tax office"]'::jsonb,0,'Citizens on Patrol assist police.','original'),
('127.746.d.13.B',4,'Community outreach programs like neighborhood watch help public safety by:','["replacing police", "building trust and reporting concerns to authorities", "ending laws", "hiding crimes"]'::jsonb,1,'Partnership improves safety.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
